const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({
    viewport: { width: 900, height: 2400 }
  });

  const htmlPath = 'file:///app/output/poster-infographic.html';
  console.log('Loading:', htmlPath);

  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Wait for fonts and rendering
  await page.waitForTimeout(2000);

  // Take screenshot
  const screenshot = await page.screenshot({
    type: 'png',
    fullPage: true
  });

  // Save to file
  const fs = require('fs');
  fs.writeFileSync('/app/output/final_poster.png', screenshot);

  console.log('Poster saved to /app/output/final_poster.png');
  console.log('Size:', screenshot.length, 'bytes');

  await browser.close();
})();

